#!/usr/bin/env python3
"""Offline replay auditor for a small SIP identity boundary (Boundary Profile 1).

The program consumes one synthetic JSON document on stdin and writes one JSON
document on stdout.  It never opens a socket, resolves a name, or contacts any
service; every decision is derived from the local registry in the document.
"""

import json
import re
import sys
from hashlib import sha256

# ---------------------------------------------------------------------------
# constants
# ---------------------------------------------------------------------------

ANON = 'sip:anonymous@anonymous.invalid'

MAX_INPUT_BYTES = 33554432
MAX_WIRE_HEX_CHARS = 131072
MAX_TOTAL_WIRE_BYTES = 8388608
MAX_REQUEST_BYTES = 65536
MAX_HEADER_BLOCK_BYTES = 32768
MAX_LINE_BYTES = 8192
MAX_HEADER_LINES = 256

ID_RE = re.compile(r'^[A-Za-z][A-Za-z0-9_-]{0,31}$')

HEXDIGITS = set('0123456789abcdefABCDEF')
DIGITS = set('0123456789')
ALNUM = set('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz')
TOKEN_CHARS = set('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz'
                  '-.!%*+`\'~')
USER_CHARS = set('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz'
                  '-_.!~*\'()')
HOST_CHARS = set('0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-')
TEL_SEPS = set('-.()')

TAG_RE = re.compile(r'[tT][aA][gG][ \t]*=[ \t]*'
                    r'([0-9A-Za-z\-.!%*+`\'~]+)\Z')
CSEQ_RE = re.compile(r'([0-9]{1,10})[ \t]+(\S+)\Z')
CALLID_RE = re.compile(r'[0-9A-Za-z\-_.@]{1,64}\Z')

COMPACT = {'f': 'from', 't': 'to', 'i': 'call-id', 'l': 'content-length'}

REQUIRED_SINGLETONS = ('from', 'to', 'call-id', 'content-length', 'cseq')


class EnvelopeError(Exception):
    """The input document is not a valid envelope (exit status 2)."""


class WireError(Exception):
    """A request could not be processed; carries the rejection reason."""

    def __init__(self, reason):
        Exception.__init__(self, reason)
        self.reason = reason


def is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


# ---------------------------------------------------------------------------
# URI language (section 2)
# ---------------------------------------------------------------------------

def valid_host(host):
    if not host or len(host) > 253:
        return False
    labels = host.split('.')
    if len(labels) < 2:
        return False
    for label in labels:
        if not (1 <= len(label) <= 63):
            return False
        for ch in label:
            if ch not in HOST_CHARS:
                return False
        if label[0] not in ALNUM or label[-1] not in ALNUM:
            return False
    last = labels[-1]
    if not (('a' <= last[0] <= 'z') or ('A' <= last[0] <= 'Z')):
        return False
    return True


def parse_sip_uri(scheme, rest):
    """Parse `user@host[:port]`; return the canonical URI or None."""
    at = rest.find('@')
    if at < 0:
        return None
    user = rest[:at]
    hostport = rest[at + 1:]
    if '@' in hostport:
        return None

    decoded = []
    i = 0
    n = len(user)
    while i < n:
        ch = user[i]
        if ch == '%':
            if i + 2 >= n:
                return None
            h1 = user[i + 1]
            h2 = user[i + 2]
            if h1 not in HEXDIGITS or h2 not in HEXDIGITS:
                return None
            byte = int(h1, 16) * 16 + int(h2, 16)
            letter = chr(byte)
            if letter not in USER_CHARS:
                return None
            decoded.append(letter)
            i += 3
        elif ch in USER_CHARS:
            decoded.append(ch)
            i += 1
        else:
            return None
    if not (1 <= len(decoded) <= 64):
        return None
    user_canon = ''.join(decoded)

    port_canon = None
    if ':' in hostport:
        host, _, port = hostport.partition(':')
        if not (1 <= len(port) <= 5):
            return None
        for ch in port:
            if ch not in DIGITS:
                return None
        value = int(port)
        if value < 1 or value > 65535:
            return None
        port_canon = str(value)
    else:
        host = hostport

    if not valid_host(host):
        return None

    canon = scheme + ':' + user_canon + '@' + host.lower()
    if port_canon is not None:
        canon += ':' + port_canon
    return canon


def parse_tel_uri(rest):
    """Parse the part after `tel:`; return the canonical URI or None."""
    if not rest.startswith('+'):
        return None
    digits = []
    for ch in rest[1:]:
        if ch in TEL_SEPS:
            continue
        if ch in DIGITS:
            digits.append(ch)
        else:
            return None
    if not (3 <= len(digits) <= 15):
        return None
    if digits[0] == '0':
        return None
    return 'tel:+' + ''.join(digits)


def parse_uri(text):
    """Return the canonical URI string for `text`, or None."""
    if not isinstance(text, str) or not text:
        return None
    low = text.lower()
    if low.startswith('sips:'):
        return parse_sip_uri('sips', text[5:])
    if low.startswith('sip:'):
        return parse_sip_uri('sip', text[4:])
    if low.startswith('tel:'):
        return parse_tel_uri(text[4:])
    return None


def uri_kind(canon):
    if canon.startswith('tel:'):
        return 'tel'
    return 'sip'


# ---------------------------------------------------------------------------
# addresses (section 3)
# ---------------------------------------------------------------------------

def scan_quoted(text, start):
    """Scan a quoted string; return the index just past the closing quote."""
    n = len(text)
    i = start + 1
    while i < n:
        ch = text[i]
        if ch == '\\':
            if i + 1 >= n:
                return None
            nxt = text[i + 1]
            if nxt != '\t' and not ('!' <= nxt <= '~'):
                return None
            i += 2
        elif ch == '"':
            return i + 1
        else:
            if ch != ' ' and ch != '\t' and not ('!' <= ch <= '~'):
                return None
            i += 1
    return None


def parse_angle(text):
    """Parse `<URI>` occupying the whole of `text`; canonical URI or None."""
    if not (text.startswith('<') and text.endswith('>')):
        return None
    inner = text[1:-1]
    if not inner:
        return None
    if '<' in inner or '>' in inner:
        return None
    for ch in inner:
        if ch == ' ' or ch == '\t':
            return None
    return parse_uri(inner)


def parse_address(text):
    """Parse a complete address; return the canonical URI or None."""
    if not isinstance(text, str):
        return None
    stripped = text.strip(' \t')
    if not stripped:
        return None
    if stripped[0] == '"':
        end = scan_quoted(stripped, 0)
        if end is None:
            return None
        i = end
        while i < len(stripped) and stripped[i] in ' \t':
            i += 1
        if i >= len(stripped) or stripped[i] != '<':
            return None
        return parse_angle(stripped[i:])
    if stripped[0] == '<':
        return parse_angle(stripped)
    if '<' in stripped:
        n = len(stripped)
        i = 0
        while True:
            if i >= n or stripped[i] not in TOKEN_CHARS:
                return None
            j = i
            while j < n and stripped[j] in TOKEN_CHARS:
                j += 1
            i = j
            k = i
            while k < n and stripped[k] in ' \t':
                k += 1
            if k < n and stripped[k] == '<':
                return parse_angle(stripped[k:])
            if k == i:
                return None
            i = k
    if '>' in stripped:
        return None
    return parse_uri(stripped)


def find_unquoted(text, needle):
    """Index of the first `needle` outside quoted strings and angle brackets."""
    in_quote = False
    in_angle = False
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if in_quote:
            if ch == '\\':
                i += 2
                continue
            if ch == '"':
                in_quote = False
        elif in_angle:
            if ch == '>':
                in_angle = False
        else:
            if ch == '"':
                in_quote = True
            elif ch == '<':
                in_angle = True
            elif ch == needle:
                return i
        i += 1
    return None


def split_on_commas(text):
    """Split a header row on commas outside quoted names and angle brackets."""
    parts = []
    in_quote = False
    in_angle = False
    start = 0
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if in_quote:
            if ch == '\\':
                i += 2
                continue
            if ch == '"':
                in_quote = False
        elif in_angle:
            if ch == '>':
                in_angle = False
        else:
            if ch == '"':
                in_quote = True
            elif ch == '<':
                in_angle = True
            elif ch == ',':
                parts.append(text[start:i])
                start = i + 1
        i += 1
    parts.append(text[start:])
    return parts


# ---------------------------------------------------------------------------
# request syntax (section 3)
# ---------------------------------------------------------------------------

def split_header_lines(block):
    """Split the header block into physical lines; raise WireError on damage."""
    lines = []
    current = bytearray()
    i = 0
    n = len(block)
    while i < n:
        byte = block[i]
        if byte == 0x0d:
            if i + 1 >= n or block[i + 1] != 0x0a:
                raise WireError('syntax')
            lines.append(bytes(current))
            current = bytearray()
            i += 2
            continue
        if byte == 0x0a:
            raise WireError('syntax')
        if byte == 0x09 or 0x20 <= byte <= 0x7e:
            current.append(byte)
            i += 1
            continue
        raise WireError('syntax')
    if current:
        lines.append(bytes(current))
    for line in lines:
        if len(line) > MAX_LINE_BYTES:
            raise WireError('syntax')
    return lines


def parse_header_fields(lines):
    """Return the header list [(name, value)] with compact names normalized."""
    headers = []
    name = None
    value = None
    for raw in lines[1:]:
        text = raw.decode('latin-1')
        if text[:1] in (' ', '\t'):
            if name is None:
                raise WireError('syntax')
            value = value.rstrip(' \t') + ' ' + text.lstrip(' \t')
            continue
        if name is not None:
            headers.append((name, value.strip(' \t')))
            name = None
            value = None
        i = 0
        while i < len(text) and text[i] in TOKEN_CHARS:
            i += 1
        if i == 0:
            raise WireError('syntax')
        raw_name = text[:i]
        j = i
        while j < len(text) and text[j] in ' \t':
            j += 1
        if j >= len(text) or text[j] != ':':
            raise WireError('syntax')
        name = raw_name.lower()
        value = text[j + 1:]
    if name is not None:
        headers.append((name, value.strip(' \t')))
    return [(COMPACT.get(n, n), v) for n, v in headers]


def parse_request(data):
    """Parse one request; return a dict of fields or raise WireError."""
    if len(data) > MAX_REQUEST_BYTES:
        raise WireError('syntax')
    index = data.find(b'\r\n\r\n')
    if index < 0:
        raise WireError('syntax')
    block = data[:index]
    body = data[index + 4:]
    if len(block) > MAX_HEADER_BLOCK_BYTES:
        raise WireError('syntax')

    lines = split_header_lines(block)
    if not lines:
        raise WireError('syntax')
    if len(lines) - 1 > MAX_HEADER_LINES:
        raise WireError('syntax')

    start = lines[0].decode('latin-1')
    parts = start.split(' ')
    if len(parts) != 3:
        raise WireError('syntax')
    method, uri_text, version = parts
    if method not in ('INVITE', 'MESSAGE'):
        raise WireError('syntax')
    if version != 'SIP/2.0':
        raise WireError('syntax')
    target = parse_uri(uri_text)
    if target is None or uri_kind(target) != 'sip':
        raise WireError('syntax')

    headers = parse_header_fields(lines)

    counts = {}
    for name, _ in headers:
        counts[name] = counts.get(name, 0) + 1
    for required in REQUIRED_SINGLETONS:
        if counts.get(required, 0) != 1:
            raise WireError('headers')

    values = {}
    rows = {}
    for name, value in headers:
        if name in REQUIRED_SINGLETONS:
            values[name] = value
        else:
            rows.setdefault(name, []).append(value)

    length_text = values['content-length']
    if not (1 <= len(length_text) <= 10):
        raise WireError('length')
    for ch in length_text:
        if ch not in DIGITS:
            raise WireError('length')
    if int(length_text) != len(body):
        raise WireError('length')

    # ---- field grammar -------------------------------------------------
    from_uri, tag = parse_from_header(values['from'])
    to_uri = parse_address(values['to'])
    if to_uri is None or uri_kind(to_uri) != 'sip':
        raise WireError('fields')
    if to_uri != target:
        raise WireError('fields')

    call_id = values['call-id']
    if not CALLID_RE.match(call_id):
        raise WireError('fields')

    cseq_match = CSEQ_RE.match(values['cseq'])
    if cseq_match is None:
        raise WireError('fields')
    cseq_number = int(cseq_match.group(1))
    if cseq_number < 1 or cseq_number > 2147483647:
        raise WireError('fields')
    if cseq_match.group(2) != method:
        raise WireError('fields')

    asserted = parse_identity_list(rows.get('p-asserted-identity'))
    preferred = parse_identity_list(rows.get('p-preferred-identity'))
    privacy = parse_privacy(rows.get('privacy'))

    return {
        'method': method,
        'target': target,
        'from_uri': from_uri,
        'tag': tag,
        'call_id': call_id,
        'cseq': cseq_number,
        'asserted': asserted,
        'preferred': preferred,
        'privacy': privacy,
        'body': body,
    }


def parse_from_header(value):
    """Parse the From header; return (canonical From URI, tag) or None."""
    semi = find_unquoted(value, ';')
    if semi is None:
        return None
    address = value[:semi].strip(' \t')
    params = value[semi + 1:].strip(' \t')
    uri = parse_address(address)
    if uri is None:
        return None
    match = TAG_RE.match(params)
    if match is None:
        return None
    tag = match.group(1)
    if not (1 <= len(tag) <= 32):
        return None
    return uri, tag


def parse_identity_list(values):
    """Parse PAI/PPI rows; return the ordered canonical list or None."""
    if values is None:
        return None
    items = []
    for row in values:
        stripped = row.strip(' \t')
        if not stripped:
            return None
        for piece in split_on_commas(stripped):
            item = piece.strip(' \t')
            if not item:
                return None
            uri = parse_address(item)
            if uri is None:
                return None
            items.append(uri)
    if not items or len(items) > 2:
        return None
    if len(items) == 2:
        first_kind = uri_kind(items[0])
        second_kind = uri_kind(items[1])
        if first_kind == second_kind:
            return None
        if first_kind == 'tel':
            items = [items[1], items[0]]
    return items


def parse_privacy(values):
    """Return 'id', 'none', 'absent', or None when malformed."""
    if values is None:
        return 'absent'
    tokens = []
    for row in values:
        for piece in row.split(';'):
            token = piece.strip(' \t').lower()
            if token == '' or token not in ('id', 'none'):
                return None
            tokens.append(token)
    if not tokens:
        return None
    has_id = 'id' in tokens
    has_none = 'none' in tokens
    if has_id and has_none:
        return None
    return 'id' if has_id else 'none'


# ---------------------------------------------------------------------------
# envelope validation (section 1)
# ---------------------------------------------------------------------------

def _object_pairs(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('duplicate object key')
        result[key] = value
    return result


def _reject_constant(name):
    raise ValueError('non-finite number')


def _reject_float(text):
    raise ValueError('fractional number')


def validate_envelope(raw):
    if len(raw) > MAX_INPUT_BYTES:
        raise EnvelopeError('input exceeds 33554432 bytes')
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        raise EnvelopeError('input is not valid UTF-8')
    try:
        document = json.loads(text, object_pairs_hook=_object_pairs,
                              parse_constant=_reject_constant,
                              parse_float=_reject_float)
    except RecursionError:
        raise EnvelopeError('input nesting is too deep')
    except ValueError as exc:
        raise EnvelopeError('input is not valid JSON: %s' % (exc,))

    if not isinstance(document, dict):
        raise EnvelopeError('top level value is not an object')
    if set(document.keys()) != {'version', 'config', 'events'}:
        raise EnvelopeError('top level keys are wrong')

    version = document['version']
    if not is_int(version) or version != 1:
        raise EnvelopeError('unsupported version')

    config = document['config']
    if not isinstance(config, dict):
        raise EnvelopeError('config is not an object')
    if set(config.keys()) != {'accounts', 'peers', 'ttl_ms', 'capacity'}:
        raise EnvelopeError('config keys are wrong')

    ttl_ms = config['ttl_ms']
    if not is_int(ttl_ms) or not (1 <= ttl_ms <= 1000000):
        raise EnvelopeError('bad ttl_ms')
    capacity = config['capacity']
    if not is_int(capacity) or not (1 <= capacity <= 10000):
        raise EnvelopeError('bad capacity')

    accounts = config['accounts']
    if not isinstance(accounts, list) or len(accounts) > 256:
        raise EnvelopeError('bad accounts')
    account_ids = set()
    alias_owner = {}
    account_aliases = {}
    account_default = {}
    for account in accounts:
        if not isinstance(account, dict):
            raise EnvelopeError('bad account entry')
        if set(account.keys()) != {'id', 'default', 'aliases'}:
            raise EnvelopeError('bad account keys')
        account_id = account['id']
        if not isinstance(account_id, str) or not ID_RE.match(account_id):
            raise EnvelopeError('bad account id')
        if account_id in account_ids:
            raise EnvelopeError('duplicate account id')
        account_ids.add(account_id)
        aliases = account['aliases']
        if not isinstance(aliases, list) or not (1 <= len(aliases) <= 8):
            raise EnvelopeError('bad aliases')
        seen = set()
        for alias in aliases:
            if not isinstance(alias, str):
                raise EnvelopeError('bad alias')
            if alias in seen:
                raise EnvelopeError('duplicate alias in account')
            seen.add(alias)
            canonical = parse_uri(alias)
            if canonical is None or canonical != alias:
                raise EnvelopeError('alias is not canonical')
            if alias == ANON:
                raise EnvelopeError('anonymous URI cannot be an alias')
            if alias in alias_owner:
                raise EnvelopeError('alias belongs to two accounts')
            alias_owner[alias] = account_id
        default = account['default']
        if not isinstance(default, str) or default not in seen:
            raise EnvelopeError('bad default alias')
        account_aliases[account_id] = list(aliases)
        account_default[account_id] = default

    peers = config['peers']
    if not isinstance(peers, list) or not (1 <= len(peers) <= 256):
        raise EnvelopeError('bad peers')
    peer_ids = set()
    peer_mode = {}
    peer_accounts = {}
    for peer in peers:
        if not isinstance(peer, dict):
            raise EnvelopeError('bad peer entry')
        if set(peer.keys()) != {'id', 'mode', 'accounts'}:
            raise EnvelopeError('bad peer keys')
        peer_id = peer['id']
        if not isinstance(peer_id, str) or not ID_RE.match(peer_id):
            raise EnvelopeError('bad peer id')
        if peer_id in peer_ids:
            raise EnvelopeError('duplicate peer id')
        peer_ids.add(peer_id)
        mode = peer['mode']
        entries = peer['accounts']
        if mode == 'access':
            if not isinstance(entries, list) or len(entries) != 0:
                raise EnvelopeError('access peer must have no accounts')
            peer_accounts[peer_id] = []
        elif mode == 'relay':
            if not isinstance(entries, list):
                raise EnvelopeError('bad peer accounts')
            for entry in entries:
                if not isinstance(entry, str) or entry not in account_ids:
                    raise EnvelopeError('peer account does not exist')
            if len(set(entries)) != len(entries):
                raise EnvelopeError('duplicate peer account')
            peer_accounts[peer_id] = list(entries)
        else:
            raise EnvelopeError('bad peer mode')
        peer_mode[peer_id] = mode

    events = document['events']
    if not isinstance(events, list) or len(events) > 10000:
        raise EnvelopeError('bad events')
    previous_t = 0
    total_wire = 0
    for event in events:
        if not isinstance(event, dict):
            raise EnvelopeError('bad event entry')
        if set(event.keys()) != {'t', 'peer', 'auth', 'egress', 'wire_hex'}:
            raise EnvelopeError('bad event keys')
        stamp = event['t']
        if not is_int(stamp) or not (0 <= stamp <= 9007199254740991):
            raise EnvelopeError('bad event time')
        if stamp < previous_t:
            raise EnvelopeError('event times descend')
        previous_t = stamp
        peer_id = event['peer']
        if not isinstance(peer_id, str) or peer_id not in peer_ids:
            raise EnvelopeError('unknown peer')
        auth = event['auth']
        if auth is not None:
            if not isinstance(auth, str) or auth not in account_ids:
                raise EnvelopeError('unknown account')
        if peer_mode[peer_id] == 'relay' and auth is not None:
            raise EnvelopeError('relay event carries authentication')
        egress = event['egress']
        if egress not in ('internal', 'external'):
            raise EnvelopeError('bad egress')
        wire = event['wire_hex']
        if not isinstance(wire, str) or len(wire) > MAX_WIRE_HEX_CHARS:
            raise EnvelopeError('bad wire_hex')
        total_wire += len(wire) // 2
    if total_wire > MAX_TOTAL_WIRE_BYTES:
        raise EnvelopeError('envelope wire budget exceeded')

    return {
        'ttl_ms': ttl_ms,
        'capacity': capacity,
        'alias_owner': alias_owner,
        'account_aliases': account_aliases,
        'account_default': account_default,
        'peer_mode': peer_mode,
        'peer_accounts': peer_accounts,
        'events': events,
    }


# ---------------------------------------------------------------------------
# policy and replay (sections 4 and 5)
# ---------------------------------------------------------------------------

def apply_policy(request, event, env):
    """Apply the trust-domain policy; return (account, identity, asserted)."""
    alias_owner = env['alias_owner']
    account_default = env['account_default']
    peer_id = event['peer']
    mode = env['peer_mode'][peer_id]
    privacy = request['privacy']
    asserted_in = request['asserted']
    preferred = request['preferred']

    if mode == 'access':
        if event['auth'] is None:
            raise WireError('auth')
        account = event['auth']
        if preferred is not None:
            for uri in preferred:
                if alias_owner.get(uri) != account:
                    raise WireError('identity')
            identity = preferred[0]
            asserted = list(preferred)
        else:
            identity = account_default[account]
            asserted = [identity]
    else:
        if preferred is not None or asserted_in is None:
            raise WireError('identity')
        owners = set()
        for uri in asserted_in:
            owner = alias_owner.get(uri)
            if owner is None:
                raise WireError('identity')
            owners.add(owner)
        if len(owners) != 1:
            raise WireError('identity')
        account = owners.pop()
        if account not in env['peer_accounts'][peer_id]:
            raise WireError('identity')
        identity = asserted_in[0]
        asserted = list(asserted_in)

    from_uri = request['from_uri']
    if alias_owner.get(from_uri) != account:
        if not (from_uri == ANON and privacy == 'id'):
            raise WireError('identity')
    return account, identity, asserted


def project(request, account, identity, asserted, egress):
    """Build the normalized outgoing projection."""
    privacy = request['privacy']
    outgoing_from = ANON if privacy == 'id' else identity
    if egress == 'external' and privacy in ('id', 'absent'):
        outgoing_pai = []
    else:
        outgoing_pai = list(asserted)
    return outgoing_from, outgoing_pai


def replay(env):
    ttl_ms = env['ttl_ms']
    capacity = env['capacity']
    ledger = {}
    results = []
    accepted = 0
    replayed = 0
